	"automation_lp_description": "\"Gli account automatizzati sono programmati per eseguire automaticamente determinate azioni attraverso le API di X, ad esempio l'invio di post contenenti le condizioni meteo di una zona. Tali account vengono creati e gestiti da altri utenti su X.\"",
