	"gift_premium_terms_footer": "\"Il prezzo dell'abbonamento regalo viene addebitato all'acquisto e non è rimborsabile. L'abbonamento può essere utilizzato una sola volta, non è sostituibile, non è combinabile e non ha un valore monetario. Ha inizio dopo che lo abbiamo controllato e assegnato al destinatario, il quale deve accettare i %1$s e le norme di X. Se il destinatario non soddisfa i requisiti di idoneità, disdice l'abbonamento o rifiuta i termini e le norme di X, il regalo non può essere riscattato e non è rimborsabile. Potrebbero essere applicate delle imposte. I termini potrebbero subire variazioni. %2$s.\"",
