	"go_to_twitter": "Passa a x.com",
	"golive__tip_broadcaster_1": "<b>CONSIGLIO:</b> grazie per aver trasmesso in diretta. Dai il benvenuto agli utenti dicendogli \\\"ciao\\\" quando si uniscono al tuo video.",
	"golive__tip_broadcaster_10": "<b>CONSIGLIO:</b> grazie per aver trasmesso in diretta su X. ≺3",
	"golive__tip_broadcaster_2": "<b>CONSIGLIO:</b> prova a menzionare gli utenti nominandoli quando si uniscono al tuo video in diretta. Si sentiranno elettrizzati!",
	"golive__tip_broadcaster_3": "<b>CONSIGLIO:</b> assicurati di andare in diretta almeno per alcuni minuti in modo da permettere agli utenti di trovarti più facilmente.",
	"golive__tip_broadcaster_4": "<b>CONSIGLIO:</b> chiedi ai tuoi spettatori da dove vengono; è un ottimo modo per rompere il ghiaccio.",
	"golive__tip_broadcaster_5": "<b>CONSIGLIO:</b> ringrazia gli utenti per essersi sintonizzati e rispondi ai loro commenti per non farli andare via.",
	"golive__tip_broadcaster_6": "<b>CONSIGLIO:</b> se perdi la connessione mentre sei in diretta, spostati dove prende meglio.",
	"golive__tip_broadcaster_7": "<b>CONSIGLIO:</b> chiedi agli utenti di seguirti in modo da ricevere una notifica le prossime volte che vai in diretta.",
	"golive__tip_broadcaster_8": "\"<b>CONSIGLIO:</b> Di' \\\"ciao\\\" appena inizi a trasmettere in diretta. Gli utenti che guarderanno il tuo video in diretta in seguito lo adoreranno.\"",
	"golive__tip_broadcaster_9": "<b>CONSIGLIO:</b> prima della fine, ringrazia gli utenti per aver guardato il tuo video in diretta.",
	"golive__tip_pre_broadcast_1": "<b>CONSIGLIO:</b> per permettere agli utenti di scoprire il tuo video, scrivi un titolo prima di andare in diretta.",
	"golive__tip_pre_broadcast_2": "<b>CONSIGLIO:</b> un titolo descrittivo aiuta gli utenti a capire meglio gli argomenti del tuo video in diretta.",
	"golive__tip_pre_broadcast_3": "<b>CONSIGLIO:</b> ti servono idee? Fai un tour, condividi un talento o parla di qualcosa che ti interessa.",
	"golive__tip_pre_broadcast_4": "<b>CONSIGLIO:</b> assicurati di avere un buon segnale telefonico prima di andare in diretta.",
	"golive__tip_pre_broadcast_5": "<b>CONSIGLIO:</b> aggiungi un hashtag al tuo titolo per aiutare gli utenti a trovare il tuo video in diretta.",
	"golive__tip_pre_broadcast_6": "<b>CONSIGLIO:</b> questi sono tutti i consigli che abbiamo per ora. Grazie per aver trasmesso in diretta su X.",
