	"identity_education_cancel": "Salta per ora",
	"identity_education_conditions": "\"Fornisco il mio consenso affinché X e AU10TIX possano utilizzare le immagini del mio documento d'identità e il mio selfie, inclusi i dati biometrici ricavati, per confermare la mia identità e per fini di X correlati alla sicurezza, comprese le misure per la prevenzione del furto d'identità. AU10TIX potrebbe memorizzare tali dati per un massimo di 30 giorni. {{}}Scopri di più{{}}\"",
	"identity_education_conditions_age_verification": "\"Accetto che X e Persona utilizzino le immagini del mio documento d'identità e la mia foto per verificare quanti anni ho. La foto non verrà memorizzata. X e xAI potrebbero memorizzare le informazioni relative alla tua età. {{}}Scopri di più{{}}\"",
	"identity_education_conditions_eea": "\"Fornisco il mio consenso affinchè X possa condividere con AU10TIX le immagini del mio documento d'identità, inclusi i dati biometrici, e i dati personali del mio profilo per confermare la mia identità.\nInoltre, fornisco il mio consenso affinché X possa memorizzare le immagini del mio documento d'identità, inclusi i dati biometrici, per un massimo di 30 giorni e possa procedere al loro utilizzo insieme ai dati del mio profilo per fini di sicurezza, incluse le misure per la prevenzione del furto d'identità. {{}}Scopri di più{{}}\"",
	"identity_education_conditions_persona_vendor": "\"Accetto che X e Persona utilizzino le immagini del mio documento d'identità e il mio selfie, inclusi i dati biometrici ricavati, per confermare la mia identità e per finalità di X correlate alla sicurezza, alla prevenzione di frodi e ai pagamenti. Persona potrebbe memorizzare tali dati per un massimo di 30 giorni. X potrebbe memorizzare il nome e cognome, l'indirizzo e gli hash per il numero del mio documento d'identità finché dispongo di un abbonamento al servizio X Premium. {{}}Scopri di più{{}}\"",
	"identity_education_description": "Cosa ti servirà:",
