	"payment_funds_insurance_footer_secondary_text": "\"﻿Qui﻿ trovi maggiori informazioni sull'assicurazione FDIC e sulle categorie di proprietà dei conti.\"",
	"payment_funds_insurance_footer_text": "I tuoi depositi sono gestiti Cross River Bank, che rientra tra i membri della FDIC, e sono assicurati da quest’ultima fino a 250.000 USD tra tutti i conti cointestati, intestati alla stessa persona fisica o intestati alla stessa persona giuridica presso la banca. Il limite assicurativo si applica singolarmente a ognuna di queste tre categorie.",
	"payment_funds_insurance_footer_text_format": "\"I tuoi depositi sono gestiti dalla Cross River Bank (\\\"la Banca\\\"), che rientra tra i membri della FDIC, e sono assicurati da quest'ultima fino a {amount} tra tutti i conti cointestati, intestati alla stessa persona fisica o intestati alla stessa persona giuridica presso la Banca. Il limite assicurativo si applica singolarmente a ognuna di queste tre categorie.\"",
	"payment_funds_insurance_sweep_disclaimer": "\"Il denaro viene detenuto dalla Cross River Bank, che rientra tra i membri della FDIC, e presso altri ﻿istituti assicurati dalla FDIC﻿. La copertura assicurativa sui depositi si applica solo se vengono rispettate ﻿determinate condizioni﻿. X Payments LLC non è una banca assicurata dalla FDIC. L'assicurazione sui versamenti copre solo il fallimento di una banca assicurata.\"",
	"payment_funds_insurance_sweep_presentation": "\"Il tuo denaro viene gestito automaticamente tramite il programma X Cash Sweep, che prevede l'accesso a un'assicurazione FDIC complessiva fino a 10.000.000 USD (soggetta a determinate limitazioni). ﻿Scopri di più﻿.\"",
