	"payment_international_wire_disclaimer_dispute_with_url_format": "\"Hai il diritto di contestare errori nella transazione. Se ritieni sia stato commesso un errore, contatta X Payments LLC entro {days} giorni chiamando il numero {phone}, scrivendo all'indirizzo {address} o visitando {url}. Puoi anche contattarci per ricevere una spiegazione dei tuoi diritti per iscritto.\"",
	"payment_international_wire_disclaimer_fees": "Include le commissioni applicate da X Payments e dalla Cross River Bank, ove applicabili.",
	"payment_international_wire_disclaimer_only_individuals": "Attualmente i bonifici bancari internazionali sono disponibili solo per le persone fisiche.",
	"payment_international_wire_disclaimer_processing_time": "Il trasferimento potrebbe avvenire prima oppure potrebbe essere ritardato o interrotto se viene riscontrato un problema.",
	"payment_international_wire_disclaimer_questions_and_complaints": "Per domande o reclami su X Payments LLC o sulla Cross River Bank, contatta le agenzie di regolamentazione statali elencate qui o il Consumer Financial Protection Bureau al numero 855-411-2372 o 855-729-2372 (per telescriventi o DTS) oppure tramite il sito www.consumerfinance.gov.",
	"payment_international_wire_disclaimer_received_amount": "I beneficiari potrebbero ricevere una somma inferiore a causa delle commissioni applicate dalla banca di destinazione e delle imposte estere.",
	"payment_international_wire_disclaimer_refund_format": "\"A meno che la somma non sia stata riscossa o versata, puoi annullare l'operazione e ottenere un rimborso completo entro {minutes} minuti dal pagamento.\"",
