	"pcf_account_lp_cta": "Ho capito",
	"pcf_account_lp_pcf_benefits_description_format": "\"Sì, l'etichetta di account satirico, di cronaca o gestito da fan garantisce che gli altri su X non siano confusi dal tuo account in quanto li informa che l'account non è affiliato al soggetto del profilo. Se non etichettato, il tuo account potrebbe violare le norme sull'autenticità.\"",
