	"ps__tip_broadcaster_11": "<b>CONSIGLIO:</b> Grazie per aver trasmesso su Periscope! ≺3",
	"ps__tip_broadcaster_2": "<b>CONSIGLIO:</b> Prova a chiamare per nome gli spettatori che si uniscono; ne saranno entusiasti!",
	"ps__tip_broadcaster_3": "<b>CONSIGLIO:</b> Assicurati di trasmettere per almeno qualche minuto per fare in modo che le persone ti trovino facilmente.",
