	"ps__tip_broadcaster_7": "<b>CONSIGLIO:</b> Chiedi ai tuoi spettatori di seguirti in modo da ricevere una notifica quando vai in diretta.",
	"ps__tip_broadcaster_8": "<b>CONSIGLIO:</b> Inizia la trasmissione salutando immediatamente. Gli spettatori del replay ne saranno contenti.",
	"ps__tip_broadcaster_9": "<b>CONSIGLIO:</b> Ringrazia gli spettatori per aver guardato prima della fine della tua trasmissione.",
