	"safety_mode_settings_half_sheet_description_1": "\"Quando rileviamo risposte, menzioni o citazioni potenzialmente di tipo offensivo o di spam, autoblocchiamo temporaneamente gli account interessati. A differenza del blocco manuale, l'autoblocco ha una durata di una settimana.\"",
