	"tipjar_input_rationale": "\"Gli utenti invieranno pagamenti al nome utente che hai indicato qui sopra. L'aggiunta del tuo nome utente e l'abilitazione delle mance potrebbero rivelare informazioni su di te disponibili nella piattaforma di pagamento, tra cui il tuo nome, la tua email e altre informazioni.\"",
