	"tipjar_input_rationale_kakao_pay": "\"Gli utenti invieranno mance al link QR che hai indicato qui sopra.\nL'aggiunta del tuo link QR e l'abilitazione delle mance potrebbero rivelare informazioni su di te disponibili nella piattaforma di pagamento, tra cui il tuo nome, la tua email e altre informazioni.\n\nIl link QR per KakaoPay può essere trovato in KakaoTalk toccando Altro > Scanner (in cima a destra) > Codice denaro, quindi l'icona degli appunti. Il link verrà copiato negli appunti e in seguito dovrai incollarlo qui sopra.\"",
	"tipjar_input_rationale_paytm": "\"Gli utenti invieranno mance al numero di telefono collegato a Paytm che hai indicato qui sopra. L'aggiunta del tuo numero di telefono e l'abilitazione delle mance potrebbero rivelare informazioni su di te disponibili nella piattaforma di pagamento, tra cui il tuo nome, la tua email, il tuo numero di telefono e altre informazioni.\"",
